/// The offset of `"internal use"` within `blob`.
internal let internalUseOffset = 0

/// The offset of `"not assigned"` within `blob`.
internal let notAssignedOffset = 13

/// The C string at `offset` within the name blob. The pointer has
/// static lifetime, as `bt_compidtostr` requires.
internal func companyName(at offset: Int) -> UnsafePointer<CChar> {
    UnsafeRawPointer(blob.utf8Start + offset)
        .assumingMemoryBound(to: CChar.self)
}

